import { ReactNode, createElement } from 'react'
import raw from './data/keywords.json'
import { BY_ID, Question } from './data'

interface Cues {
  de: string[]
  en: string[]
}

/** Key words per question, generated by scripts/keywords.py from scripts/keywords.txt. */
interface Keywords {
  /** cue words in the question */
  q: Cues
  /** words in the correct answer that go with the cue */
  a: Cues
  /** questions that sound alike but have a different answer */
  like?: string[]
}

const KEYWORDS = raw as Record<string, Keywords>

export type Lang = 'de' | 'en'

const NEGATION: Record<Lang, RegExp> = {
  de: /(?<!\p{L})(nicht|kein|keine|keinen|keinem|keiner|keines)(?!\p{L})/giu,
  en: /(?<!\p{L})(not|no one|fail)(?!\p{L})/giu,
}

const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

type Span = [start: number, end: number, kind: 'kw' | 'neg']

/** Find every occurrence of a cue, as a whole word where possible, else inside a longer word. */
function find(text: string, cue: string): [number, number][] {
  const word = new RegExp(`(?<!\\p{L})${escape(cue)}(?!\\p{L})`, 'giu')
  let hits = [...text.matchAll(word)].map((m) => [m.index!, m.index! + m[0].length] as [number, number])
  if (!hits.length) hits = [...text.matchAll(new RegExp(escape(cue), 'giu'))].map((m) => [m.index!, m.index! + m[0].length])
  return hits
}

/** Wrap cue words in <mark class="kw"> and negations in <mark class="kw-neg">. */
export function highlight(text: string, cues: string[], lang: Lang, negations: boolean): ReactNode {
  const spans: Span[] = []
  if (negations) for (const m of text.matchAll(NEGATION[lang])) spans.push([m.index!, m.index! + m[0].length, 'neg'])
  for (const c of cues) for (const [s, e] of find(text, c)) spans.push([s, e, 'kw'])
  if (!spans.length) return text
  // negations first, then longer cues; drop anything overlapping an earlier span
  spans.sort((a, b) => (a[2] === b[2] ? b[1] - b[0] - (a[1] - a[0]) : a[2] === 'neg' ? -1 : 1))
  const kept: Span[] = []
  for (const s of spans) if (!kept.some((k) => s[0] < k[1] && k[0] < s[1])) kept.push(s)
  kept.sort((a, b) => a[0] - b[0])
  const out: ReactNode[] = []
  let at = 0
  for (const [s, e, kind] of kept) {
    out.push(text.slice(at, s), createElement('mark', { key: s, className: kind === 'neg' ? 'kw-neg' : 'kw' }, text.slice(s, e)))
    at = e
  }
  out.push(text.slice(at))
  return out
}

export const keywordsFor = (q: Question): Keywords | undefined => KEYWORDS[q.id]

/** Look-alike questions for this one: general ones plus those of the user's state. */
export function lookAlikes(q: Question, state: string): Question[] {
  return (KEYWORDS[q.id]?.like ?? []).map((id) => BY_ID.get(id)!).filter((o) => o && (o.state === null || o.state === state))
}
